/*
ぷらまい1で
y軸は上が正だとしますね
はい
vec4やvec3で返して、最後のひとつを-1か1とし、-1の場合は
解が無いものとする。重解はおなじものをおけばよい。
3次方程式で解が一つだけの場合も三重解扱いでOK

https://iquilezles.org/articles/distfunctions2d/
iqさんが2次ベジエの距離関数を紹介されています
こちら：https://www.shadertoy.com/view/MlKcDD
すごい
自作：https://www.shadertoy.com/view/McVXW1
*/

const vs =
`#version 300 es
in vec3 aPosition;
out vec2 vUv;
void main(){
  vUv = aPosition.xy * 2.0;
  gl_Position = vec4(aPosition.xy * 2.0, 0.0, 1.0);
}
`;

const fs =
`#version 300 es
precision highp float;
in vec2 vUv;
out vec4 color;

uniform float uTime;

const float threshold = 1e-9;

vec2 solve1eq(vec2 c){
  if(abs(c.x) < threshold) return vec2(0.0, -1.0);
  return vec2(-c.y/c.x, 1.0); 
}

vec3 solve2eqNormal(vec2 c){
  float d = c.x*c.x - 4.0*c.y;
  if(abs(d) < threshold) return vec3(-0.5*c.x, -0.5*c.x, 1.0);
  if(d < 0.0) return vec3(0.0, 0.0, -1.0);
  float sqrtD = sqrt(d);
  return vec3(-0.5*(c.x + sqrtD), -0.5*(c.x - sqrtD), 1.0);
}

vec3 solve2eq(vec3 c){
  if(abs(c.x) < threshold) {
    vec2 ans = solve1eq(vec2(c.y, c.z));
    return vec3(ans.x, ans.x, ans.y);
  }
  return solve2eqNormal(vec2(c.y/c.x, c.z/c.x));
}

float cubeRoot(float x){
  return sign(x) * pow(abs(x), 1.0/3.0);
}

float solve3eqSpecial(float p, float q){
  float d = pow(q/2.0, 2.0) + pow(p/3.0, 3.0);

  if(abs(d) < threshold) {
    return 2.0 * cubeRoot(-0.5*q);
  }
  if(d > 0.0) {
    return cubeRoot(-0.5*q + sqrt(d)) + cubeRoot(-0.5*q - sqrt(d));
  }
  // case negative
  float theta = acos(sqrt((-27.0*q*q)/(4.0*p*p*p)));
  float k = sqrt(-4.0*p/3.0);
  float a = cos(theta/3.0)*k;
  if (abs(-a*a*a-p*a+q) < abs(a*a*a+p*a+q)) {
    return -a;
  }
  return a;
}

vec4 solve3eqNormal(vec3 c){
  float p = c.y-c.x*c.x/3.0;
  float q = 2.0*c.x*c.x*c.x/27.0 + c.z - c.x*c.y/3.0;
  float a = solve3eqSpecial(p, q);
  vec3 ans;
  if (abs(a) < threshold) {
    ans = solve2eqNormal(vec2(0.0, p));
  } else {
    ans = solve2eqNormal(vec2(a, -q/a));
  }
  vec4 result = vec4(a, ans.x, ans.y, ans.z);
  // ここでans.zが-1.0の場合はaのみが適することとなる
  // あああ...
  if (ans.z < 0.0) {
    result = vec4(a, a, a, 1.0);
  }
  result.x -= c.x/3.0;
  result.y -= c.x/3.0;
  result.z -= c.x/3.0;
  return result;
}

vec4 solve3eq(vec4 c){
  if (abs(c.x) < threshold) {
     vec3 ans = solve2eq(vec3(c.y, c.z, c.w));
     return vec4(ans.x, ans.x, ans.y, ans.z);
  }
  return solve3eqNormal(vec3(c.y/c.x, c.z/c.x, c.w/c.x));
}

float calcDistFromParam(vec3 a, vec3 b, float t){
  vec3 c = vec3(t*t, t, 1.0);
  return sqrt(pow(dot(a,c), 2.0) + pow(dot(b,c), 2.0));
}

vec2 distWithQuadraticBezier(vec2 p0, vec2 p1, vec2 p2, vec2 p){
  float a0 = p0.x - 2.0*p1.x + p2.x;
  float a1 = -2.0*p0.x + 2.0*p1.x;
  float a2 = p0.x - p.x;

  float b0 = p0.y - 2.0*p1.y + p2.y;
  float b1 = -2.0*p0.y + 2.0*p1.y;
  float b2 = p0.y - p.y;

  float c0 = a0*a0 + b0*b0;
  float c1 = 2.0*(a0*a1 + b0*b1);
  float c2 = 2.0*a0*a2 + 2.0*b0*b2 + a1*a1 + b1*b1;
  float c3 = 2.0*(a1*a2 + b1*b2);
  float c4 = a2*a2 + b2*b2;

  vec4 ans = solve3eq(vec4(4.0*c0, 3.0*c1, 2.0*c2, c3));

  // ans.w < 0.0にはならないはず...

  vec3 a = vec3(a0,a1,a2);
  vec3 b = vec3(b0,b1,b2);

  float minD = 1e9;
  float result;
  float d0 = calcDistFromParam(a, b, 0.0);
  float d1 = calcDistFromParam(a, b, 1.0);
  if (d0 < minD) {
    minD = d0; result = 0.0;
  }
  if (d1 < minD) {
    minD = d1; result = 1.0;
  }

  float tmp;
  if (ans.w > 0.0) {
    if ((ans.x > 0.0) && (ans.x < 1.0)) {
      tmp = calcDistFromParam(a, b, ans.x);
      if (tmp < minD) {
        minD = tmp; result = ans.x;
      }
    }
    if ((ans.y > 0.0) && (ans.y < 1.0)) {
      tmp = calcDistFromParam(a, b, ans.y);
      if (tmp < minD) {
        minD = tmp; result = ans.y;
      }
    }
    if ((ans.z > 0.0) && (ans.z < 1.0)) {
      tmp = calcDistFromParam(a, b, ans.z);
      if (tmp < minD) {
        minD = tmp; result = ans.z;
      }
    }
  }
  return vec2(minD, result);
}

void main(){
  vec2 uv = vUv;
  float t0 = uTime*0.8;
  float t1 = uTime*1.5;
  float t2 = -uTime*0.7;

  vec2 a = vec2(-0.5, -0.5) + 0.2*vec2(cos(t0), sin(t0));
  vec2 b = vec2(0.0, sin(t1));
  vec2 c = vec2(0.5, -0.5) + 0.2*vec2(cos(t2), sin(t2));

  vec2 sd = distWithQuadraticBezier(a, b, c, uv);

  float value = smoothstep(0.0, 0.02, sd.x);

  // 曲線上の点からuvにベクトルを引いて
  // 該当する点の接線ベクトルと外積を取ればよい
  float xx = (1.0-sd.y)*(1.0-sd.y)*a.x + 2.0*sd.y*(1.0-sd.y)*b.x + sd.y*sd.y*c.x;
  float yy = (1.0-sd.y)*(1.0-sd.y)*a.y + 2.0*sd.y*(1.0-sd.y)*b.y + sd.y*sd.y*c.y;
  vec2 v = uv - vec2(xx, yy);
  vec2 tang = vec2(
    b.x-a.x + sd.y*(a.x-2.0*b.x+c.x),
    b.y-a.y + sd.y*(a.y-2.0*b.y+c.y)
  );
  v = normalize(v);
  tang = normalize(tang);
  float op = v.x*tang.y - v.y*tang.x;

  vec3 subColor = (op>0.0 ? vec3(1.0, 0.5, 0.0) : vec3(0.0, 1.0, 1.0));

  color = vec4(vec3(value)*subColor*exp(-sd.x*2.0),1.0);
}
`;

let myShader;

function setup() {
  createCanvas(920, 690, WEBGL);
  pixelDensity(1);
  myShader = createShader(vs, fs);
  noStroke();
}

function draw() {
  clear();
  shader(myShader);
  myShader.setUniform("uTime", frameCount/60);
  plane();
}

function mouseClicked(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

